import React from 'react';
import styled from 'styled-components';
import { Link } from 'react-router-dom';
// Şimdilik diğer bileşenleri import etmeyi kaldıralım
// import Hero from '../components/home/Hero';
// import Features from '../components/home/Features';
// import PopularRecipes from '../components/home/PopularRecipes';
// import HowItWorks from '../components/home/HowItWorks';
// import Testimonials from '../components/home/Testimonials';
// import CallToAction from '../components/home/CallToAction';

// Styled components tanımlamaları
const HomeContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

// Header için yeni styled components
const Header = styled.header`
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px 0;
  margin-bottom: 20px;
`;

const Logo = styled.div`
  font-size: 2.2rem;
  font-weight: bold;
  color: #4CAF50;
  text-align: center;
  
  span {
    color: #FF9800;
  }
`;

const NavButtons = styled.div`
  display: flex;
  gap: 15px;
`;

const NavButton = styled(Link)`
  padding: 10px 20px;
  border-radius: 4px;
  text-decoration: none;
  font-weight: 500;
  
  &.primary {
    background-color: #4CAF50;
    color: white;
    
    &:hover {
      background-color: #45a049;
    }
  }
  
  &.secondary {
    background-color: transparent;
    color: #4CAF50;
    border: 1px solid #4CAF50;
    
    &:hover {
      background-color: rgba(76, 175, 80, 0.1);
    }
  }
`;

const HeroSection = styled.div`
  position: relative;
  background-color: #f8f9fa;
  background-image: url('https://images.unsplash.com/photo-1543353071-10c8ba85a904?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80');
  background-size: cover;
  background-position: center;
  padding: 100px 20px;
  text-align: center;
  border-radius: 12px;
  margin-bottom: 60px;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.15);
  overflow: hidden;
  
  &:before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(76, 175, 80, 0.85) 0%, rgba(255, 152, 0, 0.85) 100%);
    z-index: 1;
  }
  
  * {
    position: relative;
    z-index: 2;
  }
`;

const HeroTitle = styled.h1`
  color: white;
  font-size: 3.5rem;
  margin-bottom: 20px;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.2);
`;

const HeroSubtitle = styled.p`
  font-size: 1.4rem;
  color: white;
  max-width: 700px;
  margin: 0 auto 50px;
  line-height: 1.6;
  text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.2);
`;

const SearchBar = styled.div`
  display: flex;
  max-width: 700px;
  margin: 0 auto;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.2);
  border-radius: 8px;
  overflow: hidden;
  
  @media (max-width: 768px) {
    flex-direction: column;
    box-shadow: none;
  }
`;

const SearchInput = styled.input`
  flex: 1;
  padding: 20px 25px;
  border: none;
  font-size: 1.1rem;
  
  @media (max-width: 768px) {
    border-radius: 8px;
    margin-bottom: 10px;
    border: 1px solid #ddd;
  }
`;

const SearchButton = styled.button`
  background-color: #FF9800;
  color: white;
  border: none;
  padding: 20px 35px;
  cursor: pointer;
  font-weight: bold;
  font-size: 1.1rem;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #F57C00;
    transform: translateY(-2px);
  }
  
  @media (max-width: 768px) {
    border-radius: 8px;
    padding: 15px;
  }
`;

const SectionTitle = styled.h2`
  color: #333;
  font-size: 2.2rem;
  margin: 40px 0 30px;
  text-align: center;
  position: relative;
  
  &:after {
    content: '';
    display: block;
    width: 80px;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin: 15px auto;
    border-radius: 3px;
  }
`;

const CategoriesContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 25px;
  margin-bottom: 70px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(3, 1fr);
  }
  
  @media (max-width: 768px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 480px) {
    grid-template-columns: 1fr;
  }
`;

const CategoryCard = styled.div`
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  cursor: pointer;
  position: relative;
  
  &:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    
    img {
      transform: scale(1.08);
    }
  }
`;

const CategoryImage = styled.img`
  width: 100%;
  height: 180px;
  object-fit: cover;
  transition: transform 0.5s ease;
`;

const CategoryContent = styled.div`
  padding: 20px;
  text-align: center;
  background: white;
`;

const CategoryTitle = styled.h3`
  margin-bottom: 10px;
  color: #333;
  font-weight: 600;
`;

const CategoryCount = styled.span`
  color: #777;
  font-size: 0.95rem;
  background-color: #f8f9fa;
  padding: 5px 12px;
  border-radius: 20px;
  display: inline-block;
`;

const FeaturedRecipesContainer = styled.div`
  margin-bottom: 70px;
`;

const RecipesHeading = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 30px;
  
  @media (max-width: 768px) {
    flex-direction: column;
    gap: 15px;
  }
`;

const ViewAllButton = styled(Link)`
  background-color: transparent;
  color: #4CAF50;
  border: 2px solid #4CAF50;
  padding: 10px 20px;
  border-radius: 30px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #4CAF50;
    color: white;
  }
`;

const RecipesGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  
  @media (max-width: 992px) {
    grid-template-columns: repeat(2, 1fr);
  }
  
  @media (max-width: 576px) {
    grid-template-columns: 1fr;
  }
`;

const RecipeCard = styled.div`
  background-color: white;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease;
  cursor: pointer;
  
  &:hover {
    transform: translateY(-10px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    
    img {
      transform: scale(1.08);
    }
  }
`;

const RecipeImage = styled.img`
  width: 100%;
  height: 220px;
  object-fit: cover;
  transition: transform 0.5s ease;
`;

const RecipeContent = styled.div`
  padding: 25px;
`;

const RecipeTitle = styled.h3`
  margin-bottom: 15px;
  color: #333;
  font-weight: 600;
`;

const RecipeMeta = styled.div`
  display: flex;
  justify-content: space-between;
  color: #777;
  font-size: 0.95rem;
  margin-bottom: 15px;
  
  span {
    display: flex;
    align-items: center;
    gap: 5px;
  }
`;

const RecipePrice = styled.div`
  font-weight: bold;
  color: #4CAF50;
  margin-top: 15px;
  font-size: 1.2rem;
  padding-top: 15px;
  border-top: 1px solid #f0f0f0;
`;

const RecipeButton = styled(Link)`
  display: block;
  background-color: #4CAF50;
  color: white;
  text-align: center;
  padding: 12px 0;
  border-radius: 6px;
  margin-top: 15px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
  
  &:hover {
    background-color: #45a049;
    transform: translateY(-2px);
  }
`;

// Nasıl Çalışır bölümü
const HowItWorksSection = styled.section`
  margin-bottom: 70px;
  padding: 40px 0;
`;

const StepsContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  margin-top: 40px;
  
  @media (max-width: 768px) {
    grid-template-columns: 1fr;
    gap: 40px;
  }
`;

const StepCard = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 0 20px;
`;

const StepNumber = styled.div`
  background-color: #4CAF50;
  color: white;
  width: 60px;
  height: 60px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: bold;
  margin-bottom: 25px;
  box-shadow: 0 5px 15px rgba(76, 175, 80, 0.3);
`;

const StepTitle = styled.h3`
  margin-bottom: 15px;
  color: #333;
  font-size: 1.3rem;
`;

const StepDescription = styled.p`
  color: #666;
  line-height: 1.6;
`;

// Footer bölümü için
const InfoSection = styled.section`
  background: linear-gradient(135deg, #f9f9f9 0%, #f3f3f3 100%);
  padding: 60px 30px;
  border-radius: 12px;
  margin-bottom: 60px;
  text-align: center;
  position: relative;
  
  &:before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url('https://images.unsplash.com/photo-1543353071-087092ec393a?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80');
    background-size: cover;
    background-position: center;
    opacity: 0.1;
    border-radius: 12px;
  }
`;

const InfoTitle = styled.h2`
  color: #333;
  margin-bottom: 25px;
  position: relative;
  display: inline-block;
  
  &:after {
    content: '';
    display: block;
    width: 60%;
    height: 3px;
    background: linear-gradient(90deg, #4CAF50, #FF9800);
    margin: 10px auto 0;
    border-radius: 3px;
  }
`;

const InfoText = styled.p`
  max-width: 800px;
  margin: 0 auto 40px;
  font-size: 1.2rem;
  line-height: 1.6;
  color: #555;
`;

const InfoGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  
  @media (max-width: 768px) {
    grid-template-columns: 1fr;
  }
`;

const InfoCard = styled.div`
  background-color: white;
  padding: 30px 25px;
  border-radius: 12px;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);
  transition: transform 0.3s ease;
  
  &:hover {
    transform: translateY(-10px);
  }
  
  h3 {
    color: #4CAF50;
    margin-bottom: 15px;
    font-size: 1.3rem;
  }
  
  p {
    color: #666;
    line-height: 1.6;
  }
`;

const CtaSection = styled.section`
  background: linear-gradient(135deg, #4CAF50 0%, #8BC34A 100%);
  padding: 60px 30px;
  border-radius: 12px;
  margin-bottom: 60px;
  text-align: center;
  color: white;
  box-shadow: 0 5px 25px rgba(76, 175, 80, 0.3);
`;

const CtaTitle = styled.h2`
  color: white;
  margin-bottom: 20px;
  font-size: 2.2rem;
`;

const CtaText = styled.p`
  max-width: 700px;
  margin: 0 auto 30px;
  font-size: 1.2rem;
  line-height: 1.6;
`;

const CtaButton = styled(Link)`
  display: inline-block;
  background-color: white;
  color: #4CAF50;
  padding: 15px 35px;
  border-radius: 30px;
  font-size: 1.1rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
  
  &:hover {
    transform: translateY(-5px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.2);
  }
`;

const HomePage = () => {
  // Örnek kategori verileri
  const categories = [
